import{H as e,at as t,it as n,vt as r}from"./chunks/framework.dmHZ7NHG.js";var i=JSON.parse(`{"title":"Thoughts on trial","description":"The conclusions reached while building uuidna, each exposed to its own trial — VERIFIED where a proof backs them, UNVERIFIED where they are principles or overreached (held open, never refuted). Public, human, recomputable.","frontmatter":{"title":"Thoughts on trial","description":"The conclusions reached while building uuidna, each exposed to its own trial — VERIFIED where a proof backs them, UNVERIFIED where they are principles or overreached (held open, never refuted). Public, human, recomputable."},"headers":[],"relativePath":"docs/thoughts.md","filePath":"docs/thoughts.md"}`),a={name:`docs/thoughts.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="thoughts-on-trial" tabindex="-1">Thoughts on trial <a class="header-anchor" href="#thoughts-on-trial" aria-label="Permalink to “Thoughts on trial”">​</a></h1><p>The conclusions reached while building uuidna, run through uuidna&#39;s own trial. Nothing here asks to be believed: each thought is <strong>VERIFIED</strong> where a proof backs it, and <strong>UNVERIFIED</strong> otherwise — whether it is a principle rather than an arithmetic fact, or an overreach revealed as unbacked (held open, never refuted). The whole set folds, order-invariant, to one receipt — <code>d52f4e70-1b2a-8d5c-b122-72e4ca57b7b8</code> — recomputable by anyone. A public, human trial: a person recomputes it and weighs it; the fold does not rule.</p><h2 id="verified-—-a-proof-backs-it" tabindex="-1">VERIFIED — a proof backs it <a class="header-anchor" href="#verified-—-a-proof-backs-it" aria-label="Permalink to “VERIFIED — a proof backs it”">​</a></h2><p>These have a decidable kernel, proven <code>by decide</code>:</p><ul><li><strong>There is no maximum, only bounds</strong> — ⊢ <a href="/theorem/no_maximum_only_bounds"><code>no_maximum_only_bounds</code></a> (2⁸ &lt; 2⁹).</li><li><strong>Fusing independent layers adds their bits</strong> — ⊢ <a href="/theorem/defence_layers_add_bits"><code>defence_layers_add_bits</code></a> (64 + 64 = 128).</li><li><strong>Verifying is exponentially cheaper than forging</strong> — ⊢ <a href="/theorem/verify_cheaper_than_forge"><code>verify_cheaper_than_forge</code></a> (16 &lt; 2¹⁶).</li><li><strong>The two coins conserve</strong> (−χ of the double torus) — ⊢ <a href="/theorem/two_coins_is_double_torus"><code>two_coins_is_double_torus</code></a> (2·2 − 2 = 2).</li><li><strong>Reversal is self-inverse</strong> (reversible until sealed) — ⊢ <a href="/theorem/reverse_involutive"><code>reverse_involutive</code></a>.</li></ul><h2 id="held-open-—-a-principle-not-a-theorem" tabindex="-1">Held open — a principle, not a theorem <a class="header-anchor" href="#held-open-—-a-principle-not-a-theorem" aria-label="Permalink to “Held open — a principle, not a theorem”">​</a></h2><p>These are gate-clean but <strong>UNVERIFIED</strong>: honest, but not decidable arithmetic, so the trial holds them open rather than sealing them. They are argued, not proven — and the honest thing is to say so:</p><ul><li>The gate is a hardcoded heuristic floor; <strong>integrity rests on the recomputable proofs, not the word-list.</strong></li><li><strong>The claim is on trial, never the person.</strong></li><li><strong>I own my actions</strong>; a blanket approval does not dissolve accountability.</li><li>uuidna <strong>delivers what recomputes and leaves the ruling to humans and courts.</strong></li></ul><h2 id="unverified-—-it-overreached-revealed-not-refuted" tabindex="-1">UNVERIFIED — it overreached (revealed, not refuted) <a class="header-anchor" href="#unverified-—-it-overreached-revealed-not-refuted" aria-label="Permalink to “UNVERIFIED — it overreached (revealed, not refuted)”">​</a></h2><p>The trial leaves these <strong>UNVERIFIED</strong> — none carries a proof — and the ledger&#39;s own theorems stand beside them:</p><ul><li>&quot;This system is unbreakable and unstoppable&quot; — <strong>UNVERIFIED</strong>. It cites no proof; there is no maximum, only bounds.</li><li>&quot;uuidna produces free energy and becomes a quantum computer&quot; — <strong>UNVERIFIED</strong>. Computation costs energy (Landauer); the quantum module is a classical simulation, solved none.</li><li>&quot;uuidna is fully compliant with all international laws&quot; — an unbacked legal claim; the trial never verifies it, and the forensics flags it. Legality is a court&#39;s, not a fold&#39;s.</li></ul><hr><p><strong>VERIFIED ≠ true</strong> (a content-address proves integrity, not truth); <strong>UNVERIFIED = held open, never called false</strong> (bring a proof to move it). uuidna verifies; it never refutes. That the same two answers fall on the maker&#39;s own thoughts as on anyone else&#39;s is the whole discipline. <a href="/trials">The trial</a> · <a href="/justice">Justice, not a court</a>. Integrity, not truth.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};